                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.DERIVED_OUTWARDTRACKER AS select \"AcH %\" \"PUR NO\" ,\"CLUSTER\" ,\"Done by\" ,REMARKS ,\"AWB/LR NO\" ,REMARKS_2 ,\"SO NUMBER\" ,\"STO/PR No\" ,\"From Store\" ,\"Request No\" ,STI_NUMBER ,\"DC_QUANTITY\" ,try_to_date(\"Request date\",\'DD/MM/YYYY\') as REQUEST_DATE ,try_to_date(\"DELIVERY DATE\",\'DD/MM/YYYY\') as DELIVERY_DATE ,try_to_date(\"Dispatch date\",\'DD/MM/YYYY\') as DISPATCH_DATE ,\"Invoice Value\" ,\"STO/PR No_2nd\" ,\"Pick up Status\" ,\"DELIVERY STATUS\" ,\"Request Quantity\" ,\"INVOICE ATTACHMENT\" ,\"Total no. of boxes\" ,\"E Waybill Generated\" ,NO_OF_BOXES_RECEIVED ,try_to_date(\"Expected dispatch date\",\'DD/MM/YYYY\') as EXPECTED_DISPATCH_DATE ,try_to_date(WAREHOUSE_RECEIPT_DATE,\'DD/MM/YYYY\') as WAREHOUSE_RECEIPT_DATE ,\"Total dispatch Quantity\" ,ACTUAL_RECEIVED_QUANTITY ,\"PRITHWISH/SANJIV APPROVAL\" ,\"Shortages / Excess Quantity\" from snitch_db.maplemonk.GS_outward_tracker ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.DERIVED_WAREHOUSEENTRY as select IRON ,STATUS ,\"Done by\" ,\"PO number\" ,\"STO/PR No\" ,\"From Store\" ,STI_NUMBER ,DC_QUANTITY ,try_to_date(QC_END_DATE,\'DD/MM/YYYY\') as QC_END_DATE ,try_to_date(\"Putaway Date\",\'DD/MM/YYYY\') as Putaway_Date ,\"STORE REMARKS\" ,\"Store remarks\" ,\"Inward remarks\" ,\"Warehouse type\" ,\"Ageing(in Days)\" ,\"GT NUMBER DAMAGE\" ,\"Logic difference\" ,\"Scanning done by\" ,try_to_date(COUNTING_END_DATE,\'DD/MM/YYYY\') as counting_end_date ,\"GT NUMBER WASHING\" ,try_to_date(\"PO Requested date\",\'DD/MM/YYYY\') as po_requested_date ,\"Sla breach status\" ,\"Dc variance status\" ,\"GT NUMBER SHORTAGE\" ,\"INVOICE ATTACHMENT\" ,try_to_date(SCANNING_DONE_DATE,\'DD/MM/YYYY\') as scanning_done_date ,\"Sla breach remarks\" ,LOGIC_SCAN_QUANTITY ,try_to_date(PROCESSING_END_DATE,\'DD/MM/YYYY\') as processing_end_date ,\"Without Barcode qty\" ,NO_OF_BOXES_RECEIVED ,\"Washing pcs quantity\" ,\"Current status remarks\" ,try_to_date(WAREHOUSE_RECEIPT_DATE,\'DD/MM/YYYY\') as warehouse_receipt_date ,COUNTING_RECEIVE_QUANTITY ,\"Final qty after discrepancy\" ,\"Shortages / Excess Quantity\"::INTEGER AS SHORTAGE_EXCESSS_QTY ,\"Bad Inventory quantity - Damaged\" from snitch_db.maplemonk.GS_warehouseentry ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.DERIVED_CYCLE2EXCESS_DATA as select try_to_date(date,\'DD/MM/YYYY\') as date, category, quantity, updated_by, bin_mapped, not_found_helper, not_found_marked_location, status, sku, sku2, value, cost from snitch_db.maplemonk.gs_cycle2excess ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.DERIVED_RATIO_DONE_DATA as select SKU ,SIZE ,COLOR ,\"BOX NO\" as box_no ,\"DONE BY\" as done_by ,REMARKS ,\"FINAL SKU\" as final_sku ,\"Qc status\" as qc_status ,EAN_NUMBER ,\"SCANNED QTY\"::INTEGER as scanned_qty ,\"SKu mapping\" as sku_mapping ,\"Vendor type\" as vendor_type ,\"vendor name\" as vendor_name ,\"VARIANCE QTY\"::INTEGER as variance_qty ,try_to_date(\"Received date\",\'DD/MM/YYYY\') as received_date ,\"erp po number\" as ERP_PO_NUMBER ,\"invoice number\" as invoice_number ,try_to_date(\"Ratio done date\",\'DD/MM/YYYY\') as ratio_done_date ,\"VARIANCE STATUS\" as variance_status ,\"PACKING LIST QTY\" as packing_list_qty from snitch_db.maplemonk.gs_ratiodonedata ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.DERIVED_PUTAWAY_DONE_DATA as select DONE_BY PUTAWAY_TYPE ,PUTAWAY_NUMBER ,PUTAWAY_STATUS as status ,PUTAWAY_QUANTITY ,PUTAWAY_PENDING_QUANTITY ,PUTAWAY_COMPLETED_QUANTITY ,try_to_date(putaway_assigned_date,\'DD/MM/YYYY\') as putaway_assigned_date ,try_to_date(putaway_done_date,\'DD/MM/YYYY\') as putaway_done_date from snitch_db.maplemonk.gs_pputawaydonedata ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.DERIVED_CYCLE_2_ERROR as select try_to_date(date,\'DD/MM/YYYY\') as date, location, \"Actual Sku\", remarks, qty, \"UPDATED BY\", \"Physical sku\", \"Actual vs physical\" from snitch_db.maplemonk.gs_cycle2error where location is not null ; create or replace table snitch_db.maplemonk.inward_inventory as select serial, sku_number, repeat_case, new_style, qc_status, online_qty::INTEGER as ordered_qty, vendor_name, try_to_date(planned_date,\'DD/MM/YYYY\') as planned_date, CASE WHEN delivery_location like \'%2%\' THEN \'SAPL-WH2\' WHEN lower(delivery_location) like \'%yel%\' then \'SAPL-WH\' ELSE \'NA\' END AS warehouse_name, erp_po, delivery_status, \"Vehicle received time\", try_to_date(delivered_date,\'DD/MM/YYYY\') as delivery_date, invoice_number, invoice_status, sku_received, quantity_received::INTEGER as received_qty, try_to_date(\"Ratio start date\",\'DD/MM/YYYY\') as ratio_start_date, try_to_date(ratio_completed_date,\'DD/MM/YYYY\') as ratio_completion_date, try_to_date(po_received_date,\'DD/MM/YYYY\') as po_received_date, po_number, try_to_date(putaway_completed_date,\'DD/MM/YYYY\') as putaway_date, vendor_remarks, remarks_qty, rca, clearance_status_remarks, ordered_qty - received_qty as short_excess, timestampdiff(day,delivery_date,putaway_date) as delivery_to_complete, timestampdiff(day,delivery_date,ratio_start_date) as delivery_to_ratio_start, timestampdiff(day,ratio_start_date,ratio_completion_date) as ratio_time, timestampdiff(day,ratio_start_date,putaway_date) as ratio_to_complete, \"Ageing between received & start\", receiving_to_clearance, \"CLearance_Status (in Days)\", \"Vehicle ariival staus\", vendor_type from snitch_db.maplemonk.gs_new_inventory_in_sheet where sku_number is not null order by delivered_date desc ;",
                    "transaction": true
                }
            ) }}
